def solve_general_v2(n):
    N = n * (n - 1) // 2
    for y1 in range(-N, 0):
        y2 = -y1
        limit_yn_minus_1 = (N - 2) // 2
        possible_middle = list(range(y2 + 1, limit_yn_minus_1 + 1))
        for middle in itertools.combinations(possible_middle, n - 3):
            y_all = [y1, y2] + list(middle) + [N - 1 - list(middle)[-1]]
            # y_all is sorted
            sums = set()
            for i in range(n):
                for j in range(i + 1, n):
                    sums.add(y_all[i] + y_all[j])
            if len(sums) == N and all(0 <= s <= N-1 for s in sums):
                return y_all
    return None

