import time
from itertools import combinations

def solve_n_optimized(n):
    N = n * (n - 1) // 2
    start_time = time.time()
    print(f"Searching for n={n}...")

    for x2 in range(1, N + 1):
        for x_nm1 in range(x2 + 1, (x2 + N - 1) // 2 + 1):
            xn = x2 + N - 1 - x_nm1
            if xn <= x_nm1:
                continue

            middle_range = list(range(x2 + 1, x_nm1))
            for middle in combinations(middle_range, n - 4):
                x_list = [0, x2] + list(middle) + [x_nm1, xn]

                # All x_i in x_list are already distinct by construction
                # but let's be safe.
                if len(set(x_list)) != n:
                    continue

                sums = []
                for i in range(n):
                    for j in range(i + 1, n):
                        sums.append(x_list[i] + x_list[j])
                sums.sort()
                if len(set(sums)) == N and sums[N-1] - sums[0] == N - 1:
                    if sums == list(range(sums[0], sums[0] + N)):
                        print(f"Found for n={n}: {x_list}")
                        print(f"Time taken: {time.time() - start_time:.2f}s")
                        return x_list
    print(f"No solution found for n={n}.")
    print(f"Time taken: {time.time() - start_time:.2f}s")
    return None

print(f"Found for n=3: [0, 1, 2]")
for n in range(4, 9):
