def solve_n(n, S):
    M = n * (n - 1) // 2

    def backtrack(current_b):
        m = len(current_b)
        if m == n:
            sums = []
            for i in range(n):
                for j in range(i+1, n):
                    sums.append(current_b[i] + current_b[j])
            if sorted(list(set(sums))) == list(range(S, S + M)):
                return current_b
            return None

        # Current sums
        current_sums = []
        for i in range(m):
            for j in range(i+1, m):
                current_sums.append(current_b[i] + current_b[j])
        current_sums = set(current_sums)

        # Next b must satisfy:
        # 1. b_next > current_b[-1]
        # 2. b_next + current_b[0] >= S
        # 3. b_next + current_b[m-1] <= S + M - 1
        # 4. b_next + current_b[j] is not in current_sums
        # 5. b_next + current_b[j] are distinct for different j

        # From 3: b_next <= S + M - 1 - current_b[m-1]
        # From 1: b_next >= current_b[m-1] + 1

        for b_next in range(current_b[-1] + 1, S + M - 1 - current_b[m-1] + 1):
            new_sums = []
            valid = True
            for j in range(m):
                s = b_next + current_b[j]
                if s < S or s > S + M - 1 or s in current_sums:
                    valid = False
                    break
                new_sums.append(s)

            if valid:
                if len(set(new_sums)) == m:
                    res = backtrack(current_b + [b_next])
                    if res: return res
        return None

    # Try all possible b_1. Since b_1 + b_2 = S and b_1 < b_2, b_1 < S/2.
    # Also b_1 could be negative. Let's try a range.
    for b1 in range(-M, M):
        b2 = S - b1
        if b2 > b1:
            res = backtrack([b1, b2])
            if res: return res
    return None

