import itertools

def search_n_improved(n):
    M = n * (n - 1) // 2
    target_sums = set(range(M))

    # x_1 + x_2 = 0
    # x_{n-1} + x_n = M - 1
    # x_1 < x_2 < x_3 < ... < x_n

    for x1 in range(-M, 0):
        x2 = -x1
        # Remaining x_3, ..., x_{n-1}
        # We can use recursion to find x_3, ..., x_{n-1}
        # then x_n = (M-1) - x_{n-1}

        def solve_recursive(idx, current_x):
            if idx == n - 1:
                xn = (M - 1) - current_x[-1]
                if xn > current_x[-1]:
                    x = current_x + [xn]
                    sums = set()
                    for i in range(n):
                        for j in range(i + 1, n):
                            sums.add(x[i] + x[j])
                    if sums == target_sums:
                        return x
                    return None

            # Try values for x_idx
            # x_idx > x_{idx-1}
            # x_idx + x_1 must be in target_sums
            # x_idx + x_{idx-1} must be in target_sums
            # Also x_idx + x_j must be in target_sums
            for val in range(current_x[-1] + 1, M):
                # Pruning
                valid = True
                for prev_val in current_x:
                    if (val + prev_val) not in target_sums:
                        valid = False
                        break
                if valid:
                    res = solve_recursive(idx + 1, current_x + [val])
                    if res: return res
            return None

        # Need to check x1+x2=0 is in target_sums
        if 0 in target_sums:
            res = solve_recursive(2, [x1, x2])
            if res: return res
    return None

