def solve_n6():
    M = 15
    # Find 6 integers k_1 < k_2 < ... < k_6
    # such that {k_i + k_j : i < j} = {0, 1, ..., 14}
    # sum(k_i+k_j) = 105, 5 * sum(k_i) = 105 => sum(k_i) = 21

    # k_1 + k_2 = 0 (minimum sum)
    # k_5 + k_6 = 14 (maximum sum)
    # k_1 < k_2, k_1 < 0
    # k_5 < k_6, k_5 < 7

    for k1 in range(-5, 0):
        k2 = -k1
        # k_3 + k_4 = 21 - (k1+k2+k5+k6) = 21 - (0 + 14) = 7
        # k_2 < k_3 < k_4 < k_5
        for k3 in range(k2 + 1, 7):
            k4 = 7 - k3
            if k4 > k3:
                # k_5 + k_6 = 14, k_4 < k_5 < k_6
                for k5 in range(k4 + 1, 7):
                    k6 = 14 - k5
                    if k6 > k5:
                        res = [k1, k2, k3, k4, k5, k6]
                        sums = []
                        for i in range(6):
                            for j in range(i + 1, 6):
                                sums.append(res[i] + res[j])
                        if sorted(sums) == list(range(15)):
                            return res
    return None

