def solve_n6_any_S():
    M = 15
    for S in range(-10, 30):
        total_sum = M * (2 * S + M - 1) // 2
        if total_sum % 5 != 0: continue
        target_S = total_sum // 5

        # k_1+k_2 = S
        # k_5+k_6 = S+14
        # k_3+k_4 = target_S - (S + S + 14) = target_S - 2S - 14

        for k1 in range(S - 10, S): # large range
            k2 = S - k1
            if k2 <= k1: continue
            for k3 in range(k2 + 1, 20):
                k4 = target_S - 2*S - 14 - k3
                if k4 > k3:
                    for k5 in range(k4 + 1, 20):
                        k6 = S + 14 - k5
                        if k6 > k5:
                            res = [k1, k2, k3, k4, k5, k6]
                            sums = []
                            for i in range(6):
                                for j in range(i + 1, 6):
                                    sums.append(res[i] + res[j])
                            if sorted(sums) == list(range(S, S + M)):
                                return res, S
    return None

